using System.Text.Json;
using Satori.Core;

namespace Satori.Numerics.Tests;

/// <summary>
/// DW06.1: the GGML Q4_K super-block decoder and dot product, checked against an independent FP64
/// reference generated by <c>tools/q4k_reference.py</c> from the pinned ggml layout.
/// </summary>
public sealed class Q4KCodecTests
{
    private static readonly JsonElement Fixture = JsonDocument.Parse(
        File.ReadAllText(Path.Combine(GgufTests.Root, "fixtures/operators/q4k-v1.json"))).RootElement;

    private static byte[] Hex(string value) => Convert.FromHexString(value);

    private static float[] Inputs(JsonElement element) =>
        element.EnumerateArray().Select(v => v.GetSingle()).ToArray();

    [Fact]
    public void DecodedWeightsMatchReference()
    {
        foreach (var test in Fixture.GetProperty("cases").EnumerateArray())
        {
            string name = test.GetProperty("name").GetString()!;
            byte[] block = Hex(test.GetProperty("block_hex").GetString()!);
            float[] weights = new float[Q4KCodec.ElementsPerBlock];
            Q4KCodec.DecodeBlock(block, weights);
            int index = 0;
            foreach (var expected in test.GetProperty("weights").EnumerateArray())
            {
                double reference = expected.GetDouble();
                Assert.True(Math.Abs(weights[index] - reference) <= 1e-3 + 1e-4 * Math.Abs(reference),
                    $"{name} weight[{index}]: {weights[index]} vs {reference}");
                index++;
            }
            Assert.Equal(Q4KCodec.ElementsPerBlock, index);
        }
    }

    [Fact]
    public void DotMatchesReference()
    {
        foreach (var test in Fixture.GetProperty("cases").EnumerateArray())
        {
            string name = test.GetProperty("name").GetString()!;
            byte[] payload = Hex(test.GetProperty("block_hex").GetString()!);
            float[] input = Inputs(test.GetProperty("input"));
            var shape = new QuantizedMatrixShape(1, Q4KCodec.ElementsPerBlock, BlockQuantization.Q4_K);
            Assert.Equal(payload.Length, shape.ByteLength);
            float[] output = new float[1];
            QuantizedMatVec.ExecuteScalar(payload, shape, input, output);
            double reference = test.GetProperty("dot").GetDouble();
            Assert.True(Math.Abs(output[0] - reference) <= 1e-2 + 1e-4 * Math.Abs(reference),
                $"{name} dot: {output[0]} vs {reference}");
        }
    }

    [Fact]
    public void ZeroBlockDecodesToZerosAndZeroDot()
    {
        var zero = Fixture.GetProperty("cases").EnumerateArray()
            .First(c => c.GetProperty("name").GetString() == "zero");
        float[] weights = new float[Q4KCodec.ElementsPerBlock];
        Q4KCodec.DecodeBlock(Hex(zero.GetProperty("block_hex").GetString()!), weights);
        Assert.All(weights, w => Assert.Equal(0f, w));
    }

    [Fact]
    public void NonFiniteSuperBlockScaleIsRejected()
    {
        // d = +Infinity (FP16 0x7C00), everything else zero.
        byte[] payload = new byte[Q4KCodec.BytesPerBlock];
        payload[0] = 0x00;
        payload[1] = 0x7C;
        var shape = new QuantizedMatrixShape(1, Q4KCodec.ElementsPerBlock, BlockQuantization.Q4_K);
        Assert.Throws<InvalidDataException>(() => new QuantizedMatrix(payload, shape));
    }

    [Fact]
    public void ShapeRejectsRowsThatAreNotWholeSuperBlocks()
    {
        Assert.Throws<ArgumentOutOfRangeException>(() =>
            new QuantizedMatrixShape(1, 128, BlockQuantization.Q4_K));
        // 256 is a whole super-block and is accepted.
        Assert.Equal(Q4KCodec.BytesPerBlock, new QuantizedMatrixShape(1, 256, BlockQuantization.Q4_K).ByteLength);
    }
}
